// apiScanParamOverride is one row of the review step's parameters table. Endpoint "" applies to every
// endpoint carrying the parameter.
type apiScanParamOverride struct {
	Endpoint string `json:"endpoint,omitempty"`
	In       string `json:"in"`
	Name     string `json:"name"`
	Value    string `json:"value"`
	// Mode is Burp's Fixed / Dynamic: "fixed" keeps the value and exempts the parameter from the
	// audit; "dynamic" (or empty) sends the value and audits it as any other.
	Mode string `json:"mode,omitempty"`
}

// apiScanAuth is Burp's Basic / Bearer / header authentication method.
type apiScanAuth struct {
	Type     string `json:"type"` // basic | bearer | header
	Username string `json:"username,omitempty"`
	Password string `json:"password,omitempty"`
	Token    string `json:"token,omitempty"`
	Name     string `json:"name,omitempty"`
	Value    string `json:"value,omitempty"`
}

// header renders the method as the one header it sends.
func (a *apiScanAuth) header() (string, string, error) {
	switch a.Type {
	case "basic":
		if a.Username == "" {
			return "", "", errors.New("basic authentication needs a username")
		}
		return "Authorization", "Basic " + base64.StdEncoding.EncodeToString([]byte(a.Username+":"+a.Password)), nil
	case "bearer":
		if a.Token == "" {
			return "", "", errors.New("bearer authentication needs a token")
		}
		return "Authorization", "Bearer " + a.Token, nil
	case "header":
		if a.Name == "" {
			return "", "", errors.New("header authentication needs a header name")
		}
		return a.Name, a.Value, nil
	}
	return "", "", fmt.Errorf("unknown authentication type %q: expected basic, bearer or header", a.Type)
}

// applyReview applies the review step to the parsed document: excluded endpoints are dropped, and
// overridden values replace the document's. Unknown endpoints and parameters are refused by name — a
// review row that matched nothing is a typo the operator should hear about, not a silent no-op.
func applyReview(doc *apidoc.Document, req apiScanReq) error {
	if len(req.ExcludeEndpoints) > 0 {
		drop := map[string]bool{}
		for _, k := range req.ExcludeEndpoints {
			drop[k] = true
		}
		kept := doc.Operations[:0]
		matched := map[string]bool{}
		for _, op := range doc.Operations {
			if drop[op.Key()] {
				matched[op.Key()] = true
				continue
			}
			kept = append(kept, op)
		}
		for k := range drop {
			if !matched[k] {
				return fmt.Errorf("exclude_endpoints names %q, which the definition does not describe", k)
			}
		}
		if len(kept) == 0 {
			return errors.New("every endpoint was excluded, so there is nothing to scan")
		}
		doc.Operations = kept
	}
	for _, o := range req.Parameters {
		if o.Mode != "" && o.Mode != "fixed" && o.Mode != "dynamic" {
			return fmt.Errorf("parameter %s mode %q: expected fixed or dynamic", o.Name, o.Mode)
		}
		// A Postman request's path is the collection's raw URL with its {{variables}} and :path
		// variables already substituted, and the template keeps neither in a form this build can
		// re-render. Refused by name rather than accepted, because the alternative is a path that
		// is reported as the operator's value and sent garbled (vuw7).
		if o.In == "path" && doc.Format == apidoc.FormatPostman {
			return fmt.Errorf("path parameter %q cannot be overridden in a Postman collection: edit the collection's variable instead", o.Name)
		}
		hit := false
		for i := range doc.Operations {
			op := &doc.Operations[i]
			if o.Endpoint != "" && op.Key() != o.Endpoint {
				continue
			}
			if op.SetParameter(o.In, o.Name, o.Value) {
				hit = true
			}
		}
		if !hit {
			return fmt.Errorf("no endpoint has a %s parameter named %q", o.In, o.Name)
		}
	}
	return nil
}

// fixedParameters are the parameters the review marked Fixed, for the audit's skip lists: a row with
// no Endpoint applies to every endpoint carrying the parameter, so its name joins the run-wide list;
// a row naming an endpoint ("METHOD template") exempts the parameter on that endpoint only
// (burpsy-react-ui-8yjj: by name alone, fixing it on one operation stopped it being attacked on
// every other).
func fixedParameters(req apiScanReq) auditSkips {
	var out auditSkips
	for _, o := range req.Parameters {
		if o.Mode != "fixed" {
			continue
		}
		method, template, scoped := strings.Cut(strings.TrimSpace(o.Endpoint), " ")
		if !scoped || strings.TrimSpace(template) == "" {
			out.names = append(out.names, o.Name)
			continue
		}
		out.at = append(out.at, bcheck.ParameterAt{Method: method, Template: strings.TrimSpace(template), Name: o.Name})
	}
	return out
}

// handleAPIScan serves POST /api/apiscan. There is no GET: a run started here is retained in the same
// registry the crawls are (crawlRuns), so GET /api/crawl?task=N answers for it — including the
// definition summary on the run record. Two read doors onto one registry would be two chances for them
// to disagree about what a run was.
func (s *Server) handleAPIScan(w http.ResponseWriter, r *http.Request) {
	var req apiScanReq
	if err := requestJSON(w, r, http.MaxBytesReader(w, r.Body, maxRequestBodyBytes)).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON body", http.StatusBadRequest)
		return
	}
	if req.DryRun {
		// 200, not 202: nothing was accepted, because nothing was started. A check that answered 202
		// with a task id would be a dry run that leaves a task row behind.
		summary, err := s.checkAPIScan(req)
		if err != nil {
			http.Error(w, err.Error(), crawlStartStatus(err))
			return
		}
		writeJSON(w, http.StatusOK, map[string]any{"dry_run": true, "definition": summary})
		return
	}
	taskID, summary, err := s.startAPIScan(req)
	if err != nil {
		http.Error(w, err.Error(), crawlStartStatus(err))
		return
	}
	run, ok := s.crawls.get(taskID)
	state, kind := "", runKindAPIScan
	if ok {
		state = run.State
		kind = run.Kind
	}
	audit := true
	if req.Audit != nil {
		audit = *req.Audit
	}
	writeJSON(w, http.StatusAccepted, map[string]any{
		"task_id": taskID,
		"state":   state,
		"kind":    kind,
		// Echoed for the same reason /api/crawl echoes its kind: a reply that looked the same whether
		// the audit half was accepted could not be told apart from one that accepted the sweep alone.
		"audit":      audit,
		"definition": summary,
	})
}

